// Parse Podtrack HTML response
const html = $input.item.json.data;
const prev = $('Split Into Shipments').item.json;
const shipmentId = prev.id || '';
const shipmentLabel = prev.label || 'Podtrack Shipment';
const trackUrl = prev.trackUrl || 'http://47.52.146.142/podtrack/Default.aspx';

// Extract status
const statusMatch = html.match(/id="lblStatus"[^>]*>\s*:\s*([^<]+)</);
const hawbMatch = html.match(/id="lblHawb"[^>]*>\s*:\s*([^<]+)</);
const typeMatch = html.match(/id="lblservicetype"[^>]*>\s*:\s*([^<]+)</);

const currentStatus = statusMatch ? statusMatch[1].trim() : 'Unknown';
const hawb = hawbMatch ? hawbMatch[1].trim() : shipmentId;
const serviceType = typeMatch ? typeMatch[1].trim() : '';

// Extract all grid rows (tracking history)
// GridView1_ctl02..ctlN_Label1/2/3/4 = Date/Time/Location/Activity
const dateMatches = [...html.matchAll(/GridView1_ctl\d+_Label1[^>]*>([^<]+)</g)].map(m => m[1].trim());
const timeMatches = [...html.matchAll(/GridView1_ctl\d+_Label2[^>]*>([^<]+)</g)].map(m => m[1].trim());
const locMatches  = [...html.matchAll(/GridView1_ctl\d+_Label3[^>]*>([^<]+)</g)].map(m => m[1].trim());
const actMatches  = [...html.matchAll(/GridView1_ctl\d+_Label4[^>]*>([^<]+)</g)].map(m => m[1].trim());

const rows = dateMatches.map((date, i) => ({
  date,
  time: timeMatches[i] || '',
  location: locMatches[i] || '',
  activity: actMatches[i] || ''
}));

const latestEvent = rows.length > 0 ? rows[rows.length - 1] : null;
const fingerprint = `${currentStatus}|${latestEvent ? latestEvent.date + '|' + latestEvent.time + '|' + latestEvent.activity : 'none'}`;

return {
  json: {
    shipmentId,
    shipmentLabel,
    forwarder: 'podtrack',
    forwarderName: 'Thai Forwarder (Podtrack)',
    flag: '\u{1F1F9}\u{1F1ED}',
    currentStatus,
    hawb,
    serviceType,
    latestEvent,
    allEvents: rows,
    fingerprint,
    trackUrl
  }
};

// Parse Austway JSON API response
const responseData = $input.item.json;
const prev = $('Split Into Shipments').item.json;
const shipmentId = prev.id || '';
const shipmentLabel = prev.label || 'Austway Shipment';
const trackUrl = prev.trackUrl || 'https://track.austway-cargo.com';

let allEvents = [];
let currentStatus = 'Unknown';
let latestEvent = null;
let deliveryOrderNo = shipmentId;
let customerOrderNo = '';

// API returns an array directly
const arr = Array.isArray(responseData) ? responseData : (responseData.data || []);

if (arr.length > 0) {
  const shipment = arr[0];
  deliveryOrderNo = shipment.deliveryOrderNo || shipmentId;
  customerOrderNo = shipment.customerOrderNo || '';
  const traces = shipment.traces || [];

  const sorted = [...traces].sort((a, b) => (b.generatedTime || 0) - (a.generatedTime || 0));

  allEvents = sorted.map(t => {
    const d = t.generatedTime ? new Date(t.generatedTime) : null;
    return {
      date: d ? d.toLocaleDateString('en-AU', { day: '2-digit', month: 'short', year: 'numeric', timeZone: 'Australia/Sydney' }) : '',
      time: d ? d.toLocaleTimeString('en-AU', { hour: '2-digit', minute: '2-digit', timeZone: 'Australia/Sydney' }) : '',
      location: t.location || '',
      activity: t.content || t.status || '',
      status: t.status || '',
      generatedTime: t.generatedTime || 0
    };
  });

  latestEvent = allEvents.length > 0 ? allEvents[0] : null;
  currentStatus = latestEvent ? (latestEvent.status || latestEvent.activity) : 'Unknown';
}

const fingerprint = latestEvent
  ? `${latestEvent.status}|${latestEvent.activity}|${latestEvent.generatedTime}`
  : 'no-data';

return {
  json: {
    shipmentId,
    shipmentLabel,
    forwarder: 'austway',
    forwarderName: 'Austway Cargo (AU)',
    flag: '\u{1F1E6}\u{1F1FA}',
    currentStatus,
    deliveryOrderNo,
    customerOrderNo,
    latestEvent,
    allEvents,
    fingerprint,
    trackUrl
  }
};

// Compare fingerprint against stored value
// Static Data persists across workflow executions (survives n8n restarts)
const staticData = $getWorkflowStaticData('global');

const shipmentId = $input.item.json.shipmentId;
const currentFingerprint = $input.item.json.fingerprint;
const storageKey = `fp_${shipmentId}`;

const storedFingerprint = staticData[storageKey] || null;
const hasUpdate = storedFingerprint === null || storedFingerprint !== currentFingerprint;

return {
  json: {
    ...$input.item.json,
    hasUpdate,
    storedFingerprint,
    currentFingerprint,
    storageKey,
    isFirstCheck: storedFingerprint === null
  }
};

// Build the Telegram message
const d = $input.item.json;
const latest = d.latestEvent;

const timeStr = latest && latest.date ? `${latest.date}${latest.time ? ', ' + latest.time : ''}` : '';
const locationStr = latest && latest.location && latest.location.trim() ? `\n\u{1F4CD} ${latest.location.trim()}` : '';
const activityStr = latest && latest.activity ? `\n\n_${latest.activity}_` : '';

let waybillLine = '';
if (d.forwarder === 'austway') {
  waybillLine = `Waybill: \`${d.deliveryOrderNo}\``;
  if (d.customerOrderNo) waybillLine += `\nRef: \`${d.customerOrderNo}\``;
} else {
  waybillLine = `Waybill: \`${d.shipmentId}\``;
  if (d.serviceType) waybillLine += `\nType: ${d.serviceType}`;
}

const firstNote = d.isFirstCheck ? '\n\n\u{1F50D} _First check — baseline recorded._' : '';

const lines = [
  `${d.flag} *Shipment Update — ${d.forwarderName}*`,
  `\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501`,
  waybillLine,
  `Status: *${d.currentStatus}*`,
  timeStr ? `\u{1F550} ${timeStr}` : null,
  locationStr || null,
  activityStr || null,
  firstNote || null,
  ``,
  `\u{1F517} [Track Shipment](${d.trackUrl})`
].filter(x => x !== null).join('\n');

return {
  json: {
    ...$input.item.json,
    telegramMessage: lines
  }
};

// Persist new fingerprint to Static Data
const staticData = $getWorkflowStaticData('global');
staticData[$input.item.json.storageKey] = $input.item.json.currentFingerprint;
console.log(`[Tracker] Stored new fingerprint for ${$input.item.json.shipmentId}`);
return $input.item;
